package com.tmevolut.ecommerce.api.controller;
import com.tmevolut.ecommerce.api.dto.*; import com.tmevolut.ecommerce.api.entity.StatusPedido; import com.tmevolut.ecommerce.api.service.PedidoService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@Tag(name="Pedidos") @RestController @RequestMapping("/api/v1/pedidos")
public class PedidoController { private final PedidoService service; public PedidoController(PedidoService service){this.service=service;}
@GetMapping public Page<PedidoResponse> listar(@RequestParam(required=false) StatusPedido status, Pageable pageable){return service.listar(status,pageable);} @GetMapping("/{id}") public PedidoResponse buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<PedidoResponse> criar(@Valid @RequestBody PedidoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.criar(r));} @PatchMapping("/{id}/pagar") public PedidoResponse pagar(@PathVariable Long id){return service.pagar(id);} @PatchMapping("/{id}/cancelar") public PedidoResponse cancelar(@PathVariable Long id){return service.cancelar(id);} @PatchMapping("/{id}/status") public PedidoResponse status(@PathVariable Long id,@Valid @RequestBody StatusPedidoRequest r){return service.alterarStatus(id,r);}}
